-- Closed vocabularies and state invariants: a file exists exactly while the job is "succeeded".
ALTER TABLE "platform"."export_job"
  ADD CONSTRAINT export_job_kind_valid CHECK (kind IN ('trial_balance', 'general_ledger', 'journal_lines')),
  ADD CONSTRAINT export_job_format_valid CHECK (format IN ('csv', 'xlsx')),
  ADD CONSTRAINT export_job_locale_valid CHECK (locale IN ('en', 'ar')),
  ADD CONSTRAINT export_job_status_valid CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'expired')),
  ADD CONSTRAINT export_job_params_object CHECK (jsonb_typeof(params) = 'object'),
  ADD CONSTRAINT export_job_file_iff_succeeded CHECK (
    (status = 'succeeded') = (content IS NOT NULL)
    AND (status <> 'succeeded' OR (file_name IS NOT NULL AND content_type IS NOT NULL
                                   AND size_bytes = octet_length(content) AND expires_at IS NOT NULL))
  ),
  ADD CONSTRAINT export_job_failed_has_error CHECK (status <> 'failed' OR error IS NOT NULL),
  ADD CONSTRAINT export_job_branch_ids_present CHECK (scope_branch_ids IS NOT NULL);
